# ✅ Three-Failure Circuit Breaker Pattern
class SubtaskExecutor:
    MAX_FAILURES_SAME_ERROR = 3

    def execute_with_monitoring(self, subtask):
        failure_history = {}  # {error_signature: count}

        for iteration in range(10):  # Absolute max iterations
            result = actor.execute(subtask)
            feedback = monitor.evaluate(result)

            if feedback.passed:
                return result

            # Track failure signature (not just count)
            error_sig = hashlib.md5(
                feedback.error_message.encode()
            ).hexdigest()
            failure_history[error_sig] = failure_history.get(error_sig, 0) + 1

            # Check for repeated identical failure
            if failure_history[error_sig] >= self.MAX_FAILURES_SAME_ERROR:
                logger.error(
                    f"Subtask {subtask.id} failed 3x with same error: "
                    f"{feedback.error_message}"
                )
                return self._orchestrator_intervention(
                    subtask, failure_history, feedback
                )

            # Update subtask with feedback for next iteration
            subtask.add_feedback(feedback)

        raise MaxIterationsError("Exceeded 10 iterations without success")

    def _orchestrator_intervention(self, subtask, failures, last_feedback):
        """Orchestrator takes over after 3 identical failures"""
        # Option 1: Decompose subtask
        if self._is_decomposable(subtask):
            return self._decompose_and_retry(subtask)

        # Option 2: Add constraints/examples to spec
        elif self._can_add_constraints(last_feedback):
            subtask.add_constraint(last_feedback.suggested_fix)
            return self.execute_with_monitoring(subtask)

        # Option 3: Escalate to human
        else:
            raise HumanInterventionRequired(
                f"Agent stuck after {failures} attempts. "
                f"Last error: {last_feedback.error_message}"
            )
