def validate_comprehensive(output):
    issues = []  # Accumulate ALL issues

    # Run ALL independent checks
    duplicates = find_duplicates(output)
    if duplicates:
        issues.append(f"Duplicates: {duplicates}")

    schema_errors = validate_schema(output)
    if schema_errors:
        issues.append(f"Schema errors: {schema_errors}")

    structure_errors = validate_structure(output)
    if structure_errors:
        issues.append(f"Structure errors: {structure_errors}")

    logic_errors = validate_logic(output)
    if logic_errors:
        issues.append(f"Logic errors: {logic_errors}")

    # Report ALL issues together
    if issues:
        return ValidationError("\n".join(issues))

    return ValidationSuccess()
# Result: 4 independent issues = 1 Actor-Monitor cycle
