def update_subtask(self, subtask_id: int, status: str, error: Optional[str] = None):
    # Layer 1: Input validation
    if not isinstance(subtask_id, int) or subtask_id < 1:
        raise ValueError(f"Invalid subtask_id: {subtask_id}. Must be positive integer.")
    if status not in ['pending', 'in_progress', 'completed', 'failed']:
        raise ValueError(f"Invalid status: {status}. Must be one of: pending, in_progress, completed, failed.")

    # Layer 2: State validation
    plan = self._load_plan()
    if plan is None:
        raise ValueError(
            "No active plan exists. Create a plan first using: "
            "'python -m mapify_cli.recitation_manager create <task_id> <goal> <subtasks_json>'"
        )

    # Layer 3: Business logic with clear error messages
    for subtask in plan.subtasks:
        if subtask.id == subtask_id:
            subtask.status = status
            if error:
                subtask.error = error
            return

    raise ValueError(
        f"Subtask {subtask_id} not found in plan. "
        f"Valid subtask IDs: {[s.id for s in plan.subtasks]}"
    )
